import os,json,stat,time,hashlib
from pathlib import Path
start=time.monotonic();cpu=time.process_time()
root=Path('/home/qq/local-llm/models')
allow={'config.json','adapter_config.json','generation_config.json','manifest.json','MODEL_MANIFEST.json','README.md','README','LICENSE','LICENSE.txt','LICENSE.md','NOTICE','METADATA.json','metadata.json'}
out={'schema':'hepta.e3-known-ai395-model-directory-stat-readonly.v1','root':str(root),'depth_cap':2,'entry_cap':256,'metadata_file_bytes_cap':65536,'metadata_total_bytes_cap':524288,'files':[],'metadata':[],'errors':[],'truncated':False,'weights_opened':False,'weights_hashed':False,'model_loaded':False,'network_requests':0,'model_calls':0,'native_task_children':0}
seen=0;metadata_bytes=0
stack=[(root,0)]
while stack:
 d,depth=stack.pop()
 try:entries=sorted(os.scandir(d),key=lambda e:e.name)
 except OSError as e:out['errors'].append({'path':str(d),'error':type(e).__name__});continue
 for entry in entries:
  seen+=1
  if seen>256:out['truncated']=True;break
  p=Path(entry.path)
  try:st=p.lstat()
  except OSError as e:out['errors'].append({'path':str(p),'error':type(e).__name__});continue
  kind='symlink' if stat.S_ISLNK(st.st_mode) else 'directory' if stat.S_ISDIR(st.st_mode) else 'regular' if stat.S_ISREG(st.st_mode) else 'other'
  row={'path':str(p.relative_to(root)),'kind':kind,'bytes':st.st_size,'mtime_ns':st.st_mtime_ns,'ctime_ns':st.st_ctime_ns,'device':st.st_dev,'inode':st.st_ino,'mode':oct(stat.S_IMODE(st.st_mode))}
  out['files'].append(row)
  if kind=='directory' and depth<2:stack.append((p,depth+1))
  if kind=='regular' and p.name in allow and st.st_size<=65536 and metadata_bytes+st.st_size<=524288:
   flags=os.O_RDONLY|getattr(os,'O_NOFOLLOW',0)
   fd=os.open(p,flags)
   try:
    b=os.read(fd,65537);after=os.fstat(fd)
    assert len(b)==st.st_size and after.st_ino==st.st_ino and after.st_mtime_ns==st.st_mtime_ns
   finally:os.close(fd)
   metadata_bytes+=len(b);out['metadata'].append({'path':str(p.relative_to(root)),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'text':b.decode('utf-8','replace')})
 if out['truncated']:break
out.update(entries_observed=len(out['files']),metadata_bytes=metadata_bytes,wall_seconds=time.monotonic()-start,self_cpu_seconds=time.process_time()-cpu)
print(json.dumps(out,sort_keys=True))
